from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
back_motor = Motor(Port.A, Direction.CLOCKWISE)
Left_wheel = Motor(Port.B, Direction.COUNTERCLOCKWISE)
front_motor = Motor(Port.D, Direction.CLOCKWISE)
right_wheel = Motor(Port.F, Direction.CLOCKWISE)
drive_base = DriveBase(Left_wheel, right_wheel, 61, 187)

def the_ant_mission():
    # R Position left side of black bumper against the 3rd black line from the right hand corner
    # A Pusher attachment
    # P 1
    drive_base.use_gyro(True)
    drive_base.settings(straight_speed=500)
    front_motor.run_angle(500, 40)
    drive_base.straight(150)
    drive_base.turn(-70)
    drive_base.straight(560)
    drive_base.turn(70)
    drive_base.straight(250)
    drive_base.turn(43)
    front_motor.run_angle(500, -39)
    drive_base.settings(straight_speed=100)
    drive_base.straight(258)
    drive_base.straight(-30)
    drive_base.turn(85)
    drive_base.settings(straight_speed=600)
    drive_base.straight(300)
    drive_base.turn(16)
    drive_base.straight(500)

